import os, re, glob

files = sorted(glob.glob('/app/ocr/frame_*.txt'), key=lambda x: int(re.search(r'frame_(\d+)', x).group(1)))

def extract_completed_cmds(text):
    """Extract ordered list of completed commands from scrollback.
    A completed command is a >line followed by non-> lines before the next >line."""
    lines = text.splitlines()
    cmds = []
    for i, line in enumerate(lines):
        s = line.strip()
        if s.startswith('>'):
            cmd = s[1:].strip()
            if not cmd:
                continue
            has_output = False
            for j in range(i+1, len(lines)):
                nxt = lines[j].strip()
                if nxt.startswith('>'):
                    break
                if nxt:
                    has_output = True
                    break
            if has_output:
                cmds.append(cmd)
    return cmds

# For each frame, get the ordered list of completed commands
frame_cmd_lists = {}
for fp in files:
    frame = int(re.search(r'frame_(\d+)', fp).group(1))
    with open(fp, errors='replace') as f:
        text = f.read()
    frame_cmd_lists[frame] = extract_completed_cmds(text)

# Reconstruct sequence by comparing consecutive frames
# Find new commands that appear at the end of the current frame's list
# that weren't in the previous frame's list
all_moves = []
prev_list = []
for frame in sorted(frame_cmd_lists.keys()):
    curr_list = frame_cmd_lists[frame]
    # Find the overlap between prev and current lists
    # New commands are those after the overlap
    if prev_list:
        # Find how many commands from the end of prev_list appear at the start of curr_list
        max_overlap = min(len(prev_list), len(curr_list))
        overlap = 0
        for o in range(max_overlap, 0, -1):
            if prev_list[-o:] == curr_list[:o]:
                overlap = o
                break
        new_cmds = curr_list[overlap:]
    else:
        new_cmds = curr_list
    for cmd in new_cmds:
        all_moves.append((frame, cmd))
    prev_list = curr_list

for frame, cmd in all_moves:
    print(f'F{frame:03d}: {cmd}')
print(f'\nTotal moves: {len(all_moves)}')
PY
